class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request["path"] as String
        if (!is_start_with(path)) {
            return false
        }

        let user = get_jwt_user(request)
        if (user is None<HashMap<String, Any>>) {
            return false
        }

        set_current_user_info_and_log(user.getOrThrow())
        return true
    }

    public func is_start_with(request_uri: String): Bool {
        request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request["headers"] as HashMap<String, Any> ?? HashMap<String, Any>([])
        let auth = headers["Authorization"] as HashMap<String, Any> ?? HashMap<String, Any>([])

        let jwt = auth["jwt"] as String
        let user = auth["user"] as HashMap<String, Any>

        if (jwt != Nothing && user != Nothing) {
            return Some<HashMap<String, Any>>(user)
        }

        return None<HashMap<String, Any>>
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        // In actual implementation, this would set user info and log access
        println("User accessed: ${user["name"]}")
    }
}

import std.math.*

class AreaCalculator {
    let radius: Float64

    public init(radius: Float64) {
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        PI * this.radius * this.radius
    }

    public func calculate_sphere_area(): Float64 {
        4 * PI * this.radius * this.radius
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        2 * PI * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        0.5 * this.radius * this.radius * angle
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        PI * (outer_radius * outer_radius - inner_radius * inner_radius)
    }
}

