class Student <: Equatable<Student>{
    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        var flag = false
        if (this.name != that.name) {
            flag = true
        }
        if (this.grade != that.grade) {
            flag = true
        }
        if (this.major != that.major) {
            flag = true
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                flag = true
            } else {
                if (v != that.cources[k]) {
                    flag = true
                }
            }
        }
        return flag
    }

    public override operator func == (that: Student): Bool {
        if (this.name != that.name) {
            return false
        }
        if (this.grade != that.grade) {
            return false
        }
        if (this.major != that.major) {
            return false
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                return false
            }
            if (v != that.cources[k]) {
                return false
            }
        }
        return true
    }
}

class AssessmentSystem {
    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String,grade: Int64,major: String): Unit {
        this.students.add(name, Student(name, grade, major))
    }

    public func add_course_score(name: String,course: String,score: Int64): Unit {
        let student = this.students.get(name)
        match (student) {
            case Some(s) => s.cources.add(course, score)
            case None => println("Student not found")
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        let student = this.students.get(name)
        match (student) {
            case Some(s) => {
                if (s.cources.size == 0) {
                    return None<Float64>()
                }
                var sum: Int64 = 0
                var count: Int64 = 0
                for ((_, v) in s.cources) {
                    sum = sum + v
                    count = count + 1
                }
                return Some<Float64>(sum.toFloat64() / count.toFloat64())
            }
            case None => return None<Float64>()
        }
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let result = ArrayList<String>()
        for ((name, student) in this.students) {
            for ((_, score) in student.cources) {
                if (score < 60) {
                    result.add(name)
                    break
                }
            }
        }
        return result
    }

    public func get_course_average(course: String): Option<Float64> {
        var sum: Int64 = 0
        var count: Int64 = 0
        for ((_, student) in this.students) {
            match (student.cources.get(course)) {
                case Some(score) => {
                    sum = sum + score
                    count = count + 1
                }
                case None => {}
            }
        }
        if (count == 0) {
            return None<Float64>()
        }
        return Some<Float64>(sum.toFloat64() / count.toFloat64())
    }

    public func get_top_student(): Option<String> {
        var max_gpa: Float64 = -1.0
        var top_student: Option<String> = None<String>()
        for ((name, _) in this.students) {
            let gpa = this.get_gpa(name)
            match (gpa) {
                case Some(value) => {
                    if (value > max_gpa) {
                        max_gpa = value
                        top_student = Some<String>(name)
                    }
                }
                case None => {}
            }
        }
        return top_student
    }
}

