import std.collection.ArrayList
import std.time.DateTime

class Classroom {

    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if (!this.courses.contains(course)) {
            this.courses.add(course)
        }
    }

    public func remove_course(course: Course): Unit {
        let index = this.courses.indexOf(course)
        if (index != -1) {
            this.courses.remove(at: index)
        }
    }

    public func is_free_at(check_time: String): Bool {
        let checkDateTime = DateTime.parse(check_time)
        for (course in this.courses) {
            let startDateTime = DateTime.parse(course.start_time)
            let endDateTime = DateTime.parsecourse.end_time)
            if (checkDateTime >= startDateTime && checkDateTime <= endDateTime) {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        let newStart = DateTime.parse(new_course.start_time)
        let newEnd = DateTime.parse(new_course.end_time)

        for (course in this.courses) {
            let start = DateTime.parse(course.start_time)
            let end = DateTime.parse(course.end_time)

            if (!(newEnd < start || newStart > end)) {
                return false
            }
        }
        return true
    }
}

