                result.add(student["name"] ?? "")
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashSet<String>()
        for student in this.students {
            let major = student["major"] ?? ""
            if (major != "") {
                majors.add(major)
            }
        }
        return ArrayList<String>(majors)
    }

    public func get_most_popular_class_in_major(major: String): String {
        let class_counts = HashMap<String, Int64>()
        for student_name in get_students_by_major(major) {
            let classes = this.students_registration_classes.get(student_name) ?? ArrayList<String>()
            for class_name in classes {
                let count = class_counts.get(class_name) ?? 0
                class_counts.add(class_name, count + 1)
            }
        }

        var max_count: Int64 = 0
        var popular_class = ""
        for (class_name, count) in class_counts {
            if (count > max_count) {
                max_count = count
                popular_class = class_name
            }
        }
        return popular_class
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result: Int64 = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m > n) { return 0 }
        if (m == 0 || m == n) { return 1 }
        return factorial(n) / (factorial(m) * factorial(n - m))
    }

    public static func count_all(n: Int64): Int64 {
        if (n >= 63) { return Int64.MAX } // Prevent overflow
        return (1 << n) - 1 // 2^n - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        _select(0, ArrayList<String>(Array<String>(m, repeat: "")), 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (i in 1..datas.size + 1) {
            let current = select(i)
            for (item in current) {
                result.add(item)
            }
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        if (resultIndex == resultList.size) {
            result.add(ArrayList<String>(resultList))
            return
        }
        if (dataIndex >= datas.size) {
            return
        }
        resultList[resultIndex] = datas[dataIndex]
        _select(dataIndex + 1, resultList, resultIndex + 1, result)
        _select(dataIndex + 1, resultList, resultIndex, result)
    }
}

import std.math.abs

class ComplexNumber <: Equatable<ComplexNumber> {

    public var real: Float64
    public var imaginary: Float64

    public init(real: Float64, imaginary: Float64) {
        this.real = real
        this.imaginary = imaginary
    }

    public override operator func != (that: ComplexNumber): Bool {
        return this.real != that.real || this.imaginary != that.imaginary
    }

    public override operator func == (that: ComplexNumber): Bool {
        return this.real == that.real && this.imaginary == that.imaginary
    }
}

class ComplexCalculator {

    public init() { }

    public static func add(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        ComplexNumber(c1.real + c2.real, c1.imaginary + c2.imaginary)
    }

    public static func subtract(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        ComplexNumber(c1.real - c2.real, c1.imaginary - c2.imaginary)
    }

    public static func multiply(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let real = c1.real * c2.real - c1.imaginary * c2.imaginary
        let imaginary = c1.real * c2.imaginary + c1.imaginary * c2.real
        ComplexNumber(real, imaginary)
    }

    public static func divide(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let denominator = c2.real * c2.real + c2.imaginary * c2.imaginary
        let real = (c1.real * c2.real + c1.imaginary * c2.imaginary) / denominator
        let imaginary = (c1.imaginary * c2.real - c1.real * c2.imaginary) / denominator
        ComplexNumber(real, imaginary)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        let content = readFile(file_name)
        let lines = content.split("\n")

        if (lines.size > 0) {
            let header = lines[0].split(",")
            for (field in header) {
                title.add(field.trim())
            }

            for (i in 1..lines.size) {
                let row = ArrayList<String>()
                let fields = lines[i].split(",")
                for (field in fields) {
                    row.add(field.trim())
                }
                data.add(row)
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = open(file_name, "w")
            for (row in data) {
                let line = row.join(",")
                file.write(line + "\n")
            }
            file.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, old_data) = read_csv(save_file_name)
        let new_data = ArrayList<ArrayList<String>>()

        for (row in old_data) {
            if (N >= 0 && N < row.size) {
                let new_row = ArrayList<String>()
                new_row.add(row[N].toUpper())
                new_data.add(new_row)
            }
        }

        let new_file_name = save_file_name.replace(".csv", "_process.csv")
        let all_data = ArrayList<ArrayList<String>>()
        all_data.add(title)
        for (row in new_data) {
            all_data.add(row)
        }

        return write_csv(all_data, new_file_name)
    }
}

