import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        var sum: Int64 = 0
        for (i in 0..data.size) {
            sum += data[i]
        }
        let meanValue = sum.toFloat64() / data.size.toFloat64()
        return round(meanValue * 100.0) / 100.0
    }

    public func median(data: ArrayList<Int64>): Float64 {
        var sortedData = ArrayList<Int64>(data)
        sort(sortedData)
        let n = sortedData.size
        if (n % 2 == 0) {
            return round((sortedData[n/2 - 1] + sortedData[n/2]).toFloat64() / 2.0 * 100.0) / 100.0
        } else {
            return round(sortedData[n/2].toFloat64() * 100.0) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (i in 0..data.size) {
            let key = data[i]
            if (freq.contains(key)) {
                freq[key] = freq[key]! + 1
            } else {
                freq.add(key, 1)
            }
        }

        var maxCount: Int64 = 0
        var modes = ArrayList<Int64>()
        for (kv in freq) {
            if (kv.value > maxCount) {
                maxCount = kv.value
                modes.clear()
                modes.add(kv.key)
            } else if (kv.value == maxCount) {
                modes.add(kv.key)
            }
        }
        sort(modes)
        return modes
    }
}

