        var sum = 0.0
        for (i in 0..this.data.size) {
            sum += this.data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        var min_val = this.data[0]
        for (i in 1..this.data.size) {
            if (this.data[i] < min_val) {
                min_val = this.data[i]
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        var max_val = this.data[0]
        for (i in 1..this.data.size) {
            if (this.data[i] > max_val) {
                max_val = this.data[i]
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        let mean = this.get_sum() / Float64(this.data.size)
        var variance = 0.0
        for (i in 0..this.data.size) {
            variance += (this.data[i] - mean) * (this.data[i] - mean)
        }
        variance /= Float64(this.data.size)
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        let variance = this.get_variance()
        return round(sqrt(variance) * 100) / 100
    }

