        return 1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.pow

class DataStatistics4 {

    private static func mean(data: ArrayList<Float64>): Float64 {
        let sum = data.fold(0.0, {acc, x => acc + x})
        return sum / data.size.toFloat64()
    }

    private static func variance(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let sum = data.fold(0.0, {acc, x => acc + pow(x - m, 2.0)})
        return sum / data.size.toFloat64()
    }

    private static func covariance(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let m1 = mean(data1)
        let m2 = mean(data2)
        let sum = (0..data1.size).fold(0.0, {acc, i => acc + (data1[i] - m1) * (data2[i] - m2)})
        return sum / data1.size.toFloat64()
    }

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let cov = covariance(data1, data2)
        let sd1 = sqrt(variance(data1))
        let sd2 = sqrt(variance(data2))
        return cov / (sd1 * sd2)
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let sd = sqrt(variance(data))
        let n = data.size.toFloat64()
        let sum = data.fold(0.0, {acc, x => acc + pow((x - m) / sd, 3.0)})
        return sum * n / ((n - 1.0) * (n - 2.0))
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let m = mean(data)
        let sd = sqrt(variance(data))
        let n = data.size.toFloat64()
        let sum = data.fold(0.0, {acc, x => acc + pow((x - m) / sd, 4.0)})
        return sum * n * (n + 1.0) / ((n - 1.0) * (n - 2.0) * (n - 3.0)) - 
               3.0 * pow(n - 1.0, 2.0) / ((n - 2.0) * (n - 3.0))
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let sqrt_2pi = sqrt(2.0 * 3.141592653589793)
        let coeff = 1.0 / (sigma * sqrt_2pi)

        for x in data {
            let exponent = -0.5 * pow((x - mu) / sigma, 2.0)
            result.add(exp(exponent) * coeff)
        }
        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let result = ArrayList<Rune>()
        for (c in ciphertext.runes()) {
            if (c >= r'a' && c <= r'z') {
                let shifted = ((c - r'a' - shift + 26) % 26) + r'a'
                result.add(shifted)
            } else if (c >= r'A' && c <= r'Z') {
                let shifted = ((c - r'A' - shift + 26) % 26) + r'A'
                result.add(shifted)
            } else {
                result.add(c)
            }
        }
        return String(result)
    }

    public func vigenere_decipher(ciphertext: String): String {
        let result = ArrayList<Rune>()
        let key_iter = this.key.runes().cycle()
        for ((c, k) in zip(ciphertext.runes(), key_iter)) {
            if (c >= r'a' && c <= r'z') {
                let k_val = k - r'a'
                let decrypted = ((c - r'a' - k_val + 26) % 26) + r'a'
                result.add(decrypted)
            } else if (c >= r'A' && c <= r'Z') {
                let k_val = (k.toLower() - r'a')
                let decrypted = ((c - r'A' - k_val + 26) % 26) + r'A'
                result.add(decrypted)
            } else {
                result.add(c)
            }
        }
        return String(result)
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        if (rails == 1) {
            return encrypted_text
        }

        let arr = ArrayList<ArrayList<Rune>>()
        for (_ in 0..rails) {
            arr.add(ArrayList<Rune>())
        }

        let pattern = ArrayList<Int64>()
        for (i in 0..rails) {
            pattern.add(i)
        }
        for (i in (rails-2)..1:-1) {
            pattern.add(i)
        }

        let pattern_cycle = pattern.cycle()
        let indices = ArrayList<Int64>()
        for (_ in 0..encrypted_text.size) {
            indices.add(pattern_cycle.next() ?? 0)
        }

        let chars = ArrayList<Rune>(encrypted_text.runes())
        for ((i, c) in zip(indices, chars)) {
            arr[i].add(c)
        }

        let result = ArrayList<Rune>()
        for (row in arr) {
            result.addAll(row)
        }

        return String(result)
    }
}

extension Iterator {
    func cycle(): Iterator<T> {
        while (true) {
            for (elem in this) {
                yield elem
            }
        }
    }
}

extension Rune {
    func toLower(): Rune {
        if (this >= r'A' && this <= r'Z') {
            return this + (r'a' - r'A')
        }
        return this
    }
}

