import std.collection.ArrayList

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..state.size) {
            for (j in 0..state[i].size) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            let new_row = ArrayList<Int64>()
            for (item in row) {
                new_row.add(item)
            }
            new_state.add(new_row)
        }

        let (i, j) = find_blank(state)

        if (direction == "up" && i > 0) {
            new_state[i][j] = new_state[i-1][j]
            new_state[i-1][j] = 0
        } else if (direction == "down" && i < state.size-1) {
            new_state[i][j] = new_state[i+1][j]
            new_state[i+1][j] = 0
        } else if (direction == "left" && j > 0) {
            new_state[i][j] = new_state[i][j-1]
            new_state[i][j-1] = 0
        } else if (direction == "right" && j < state[i].size-1) {
            new_state[i][j] = new_state[i][j+1]
            new_state[i][j+1] = 0
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state)

        if (i > 0) { moves.add("up") }
        if (i < state.size-1) { moves.add("down") }
        if (j > 0) { moves.add("left") }
        if (j < state[i].size-1) { moves.add("right") }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        open_list.add((this.initial_state, ArrayList<String>()))
        let visited = HashSet<ArrayList<ArrayList<Int64>>>()

        while (open_list.size > 0) {
            let (current_state, path) = open_list.remove(at: 0)

            if (current_state == this.goal_state) {
                return path
            }

            if (!visited.contains(current_state)) {
                visited.add(current_state)
                let possible_moves = get_possible_moves(current_state)

                for (move in possible_moves) {
                    let new_state = move(current_state, move)
                    let new_path = ArrayList<String>()
                    for (step in path) {
                        new_path.add(step)
                    }
                    new_path.add(move)
                    open_list.add((new_state, new_path))
                }
            }
        }

        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {
    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if (recv.is_full_with_one_more_email(size)) {
            return false
        }

        let email = HashMap<String, Any>([
            ("sender", this.addr),
            ("receiver", recv.addr),
            ("content", content),
            ("size", size),
            ("time", DateTime.now()),
            ("state", "unread")
        ])
        recv.inbox.add(email, at: 0)
        return true
    }

    public func fetch(): HashMap<String, Any> {
        for (i in 0..this.inbox.size) {
            if (this.inbox[i]["state"] == "unread") {
                this.inbox[i]["state"] = "read"
                return this.inbox[i]
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied = this.get_occupied_size()
        return occupied + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var total: Int64 = 0
        for (i in 0..this.inbox.size) {
            total += this.inbox[i]["size"] as Int64
        }
        return total
    }

    public func clear_inbox(size: Int64): Unit {
        let needed_space = size - (this.capacity - this.get_occupied_size())
        if (needed_space <= 0) {
            return
        }

        var removed: Int64 = 0
        while (removed < needed_space && this.inbox.size > 0) {
            let oldest = this.inbox[this.inbox.size - 1]
            removed += oldest["size"] as Int64
            this.inbox.remove(at: this.inbox.size - 1)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'
        */
        let runes = plaintext.toRuneArray()
        let mut cipher_runes = ArrayList<Rune>()

        for (rune in runes) {
            let base = if (rune >= r'a' && rune <= r'z') { r'a' }
                       else if (rune >= r'A' && rune <= r'Z') { r'A' }
                       else { continue }

            let diff = rune - base
            let shifted_diff = (diff + shift) % 26
            let shifted_rune = base + shifted_diff
            cipher_runes.add(shifted_rune)
        }

        return String(cipher_runes)
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'
        */
        let plain_runes = plain_text.toRuneArray()
        let key_runes = this.key.toRuneArray()
        let mut cipher_runes = ArrayList<Rune>()

        for (i in 0..plain_runes.size) {
            let plain_rune = plain_runes[i]
            let key_rune = key_runes[i % key_runes.size]

            if (!(plain_rune >= r'a' && plain_rune <= r'z')) {
                continue
            }

            let plain_offset = plain_rune - r'a'
            let key_offset = key_rune - r'a'
            let cipher_offset = (plain_offset + key_offset) % 26
            let cipher_rune = r'a' + cipher_offset
            cipher_runes.add(cipher_rune)
        }

        return String(cipher_runes)
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'
        */
        if (rails <= 1) {
            return plain_text
        }

        let runes = plain_text.toRuneArray()
        let mut rail_arrays = ArrayList<ArrayList<Rune>>()

        for (_ in 0..rails) {
            rail_arrays.add(ArrayList<Rune>())
        }

        var rail = 0
        var down = true

        for (rune in runes) {
            rail_arrays[rail].add(rune)

            if (rail == 0) {
                down = true
            } else if (rail == rails - 1) {
                down = false
            }

            rail = if (down) { rail + 1 } else { rail - 1 }
        }

        let mut result = ArrayList<Rune>()
        for (rail_array in rail_arrays) {
            result.addAll(rail_array)
        }

        return String(result)
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        this.prepare(expression)
        let stack = ArrayList<Decimal>()

        for token in postfix_stack {
            if is_operator(token) {
                let second_value = stack.remove(at: stack.size - 1)
                let first_value = stack.remove(at: stack.size - 1)
                stack.add(_calculate(first_value, second_value, token))
            } else {
                stack.add(Decimal.parse(token))
            }
        }

        return stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let transformed = ExpressionCalculator.transform(expression)
        let operator_stack = ArrayList<String>()

        var i = 0
        while i < transformed.length {
            let c = transformed.substring(i, i+1)
            if c == " " {
                i += 1
                continue
            }

            if c == "(" {
                operator_stack.add(c)
            } else if c == ")" {
                while operator_stack[operator_stack.size - 1] != "(" {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.remove(at: operator_stack.size - 1)
            } else if is_operator(c) {
                while operator_stack.size > 0 && 
                      this.compare(c, operator_stack[operator_stack.size - 1]) {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.add(c)
            } else {
                var number = ""
                while i < transformed.length && 
                      !is_operator(transformed.substring(i, i+1)) && 
                      transformed.substring(i, i+1) != " " {
                    number += transformed.substring(i, i+1)
                    i += 1
                }
                postfix_stack.add(number)
                continue
            }
            i += 1
        }

        while operator_stack.size > 0 {
            postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" => true
            case "-" => true
            case "*" => true
            case "/" => true
            case "(" => true
            case ")" => true
            case "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_pri = operat_priority[get_operator_index(cur)]
        let peek_pri = operat_priority[get_operator_index(peek)]
        cur_pri >= peek_pri
    }

    func get_operator_index(op: String): Int64 {
        match (op) {
            case "+" => 0
            case "-" => 1
            case "*" => 2
            case "/" => 3
            case "(" => 4
            case ")" => 5
            case "%" => 6
            case _ => 7
        }
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        let regex = Regex("\\s+")
        regex.replaceAll(expression, "")
    }
}

