import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        for (xi in x_interp) {
            var i = 0
            while (i < x.size - 1 && x[i + 1] < xi) {
                i += 1
            }

            if (i == x.size - 1) {
                result.add(y[y.size - 1])
            } else {
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[i]
                let y1 = y[i + 1]

                let t = (xi - x0) / (x1 - x0)
                let yi = y0 + t * (y1 - y0)
                result.add(yi)
            }
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        for (k in 0..x_interp.size) {
            let xi = x_interp[k]
            let yi = y_interp[k]

            // Find x interval
            var i = 0
            while (i < x.size - 1 && x[i + 1] < xi) {
                i += 1
            }

            // Find y interval
            var j = 0
            while (j < y.size - 1 && y[j + 1] < yi) {
                j += 1
            }

            if (i == x.size - 1 || j == y.size - 1) {
                result.add(z[i][j])
            } else {
                // Bilinear interpolation
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[j]
                let y1 = y[j + 1]

                let z00 = z[i][j]
                let z01 = z[i][j + 1]
                let z10 = z[i + 1][j]
                let z11 = z[i + 1][j + 1]

                let tx = (xi - x0) / (x1 - x0)
                let ty = (yi - y0) / (y1 - y0)

                let zi = z00 * (1 - tx) * (1 - ty) + 
                         z10 * tx * (1 - ty) + 
                         z01 * (1 - tx) * ty + 
                         z11 * tx * ty
                result.add(zi)
            }
        }

        return result
    }
}

