class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            match (part.toInt64()) {
                case Some<Int64>(n) => {
                    if (n < 0 || n > 255) {
                        return false
                    }
                }
                case None<Int64> => return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        let result = ArrayList<String>()
        if (!this.is_valid()) {
            return result
        }
        result.addAll(this.ip_address.split("."))
        return result
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let octets = this.get_octets()
        let binary_parts = ArrayList<String>()
        for (octet in octets) {
            let n = octet.toInt64().getOrThrow()
            let binary = (0..8)
                .map({i: Int64 => if ((n & (1 << (7 - i))) != 0) { "1" } else { "0" }})
                .join("")
            binary_parts.add(binary)
        }
        return binary_parts.join(".")
    }
}

