import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var observedSum: Float64 = 0.0
        var expectedSum: Float64 = 0.0
        var total: Float64 = 0.0

        for (i in 0..k) {
            for (j in 0..k) {
                total += testData[i][j].toFloat64()
            }
        }

        for (i in 0..k) {
            observedSum += testData[i][i].toFloat64()

            var rowSum: Float64 = 0.0
            var colSum: Float64 = 0.0

            for (j in 0..k) {
                rowSum += testData[i][j].toFloat64()
                colSum += testData[j][i].toFloat64()
            }

            expectedSum += rowSum * colSum
        }

        let po = observedSum / total
        let pe = expectedSum / (total * total)

        return if (abs(1.0 - pe) < 0.000001) { 1.0 } else { (po - pe) / (1.0 - pe) }
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pjSum: Float64 = 0.0
        var PiArray = ArrayList<Float64>()

        // Calculate p_j for each category
        for (j in 0..k) {
            var categorySum: Float64 = 0.0
            for (i in 0..N) {
                categorySum += testData[i][j].toFloat64()
            }
            let pj = categorySum / (N * n).toFloat64()
            pjSum += pj * pj
        }

        // Calculate P_i for each subject
        for (i in 0..N) {
            var innerSum: Float64 = 0.0
            for (j in 0..k) {
                innerSum += testData[i][j].toFloat64() * (testData[i][j].toFloat64() - 1.0)
            }
            let Pi = innerSum / (n * (n - 1)).toFloat64()
            PiArray.add(Pi)
        }

        // Calculate P_bar (mean of Pi)
        var Pbar: Float64 = 0.0
        for (Pi in PiArray) {
            Pbar += Pi
        }
        Pbar /= N.toFloat64()

        // Calculate Fleiss' kappa
        let Pe = pjSum
        return if (abs(1.0 - Pe) < 0.000001) { 1.0 } else { (Pbar - Pe) / (1.0 - Pe) }
    }
}

import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        if (this.word_list.size == 0) {
            return ""
        }

        let regex = Regex("[^a-zA-Z\\s]")
        let clean_sentence = regex.replaceAll(sentence, "")
        let words = clean_sentence.split(" ")

        var longest = ""
        for (word in words) {
            if (this.word_list.contains(word) && word.size > longest.size) {
                longest = word
            }
        }

        return longest
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {
    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let numIcons = ICONS.size
        let board = ArrayList<ArrayList<String>>([])

        let rand = Random()
        for (i in 0..rows) {
            let row = ArrayList<String>([])
            for (j in 0..cols) {
                let index = rand.next(numIcons)
                row.add(ICONS[index], at: j)
            }
            board.add(row, at: i)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        // Check if positions are within bounds
        if (x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1]) {
            return false
        }
        if (x2 < 0 || x2 >= BOARD_SIZE[0] || y2 < 0 || y2 >= BOARD_SIZE[1]) {
            return false
        }

        // Check if same position
        if (x1 == x2 && y1 == y2) {
            return false
        }

        // Check if same icon
        if (board[x1][y1] != board[x2][y2]) {
            return false
        }

        // Check if path exists
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited = ArrayList<(Int64, Int64)>([])
        return dfs(pos1, pos2, visited, 0)
    }

    func dfs(current: (Int64, Int64), target: (Int64, Int64), visited: ArrayList<(Int64, Int64)>, turns: Int64): Bool {
        if (turns > 2) {
            return false
        }
        if (current == target) {
            return true
        }

        let (x, y) = current
        visited.add(current, at: visited.size)

        let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for (dx, dy in directions) {
            let nx = x + dx
            let ny = y + dy

            while (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1]) {
                if (!MahjongConnect.contains(visited, (nx, ny))) {
                    let nextPos = (nx, ny)
                    if (board[nx][ny] == " " || nextPos == target) {
                        if (dfs(nextPos, target, visited, turns)) {
                            return true
                        }
                    } else {
                        break
                    }
                }
                nx += dx
                ny += dy
            }

            if (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1]) {
                if (!MahjongConnect.contains(visited, (nx, ny))) {
                    let nextPos = (nx, ny)
                    if (board[nx][ny] == " " || nextPos == target) {
                        if (dfs(nextPos, target, visited, turns + 1)) {
                            return true
                        }
                    }
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (icon in row) {
                if (icon != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if (center - diff == -1 || center + diff == string.size) {
            return 0
        }
        if (string[center - diff] == string[center + diff]) {
            return 1 + palindromic_length(center, diff + 1, string)
        }
        return 0
    }

    public func palindromic_string(): String {
        let max_length = this.input_string.size
        if (max_length == 0) {
            return ""
        }

        let processed_string = "|" + this.input_string.runes().map({r: Rune => r.toString()}).join("|") + "|"
        let palindromic_lengths = Array<Int64>(size: processed_string.size)

        var center = 0
        var right = 0
        var max_len = 0
        var max_center = 0

        for (i in 0..processed_string.size) {
            let mirror = 2 * center - i

            if (i < right) {
                palindromic_lengths[i] = min(right - i, palindromic_lengths[mirror])
            }

            let expanded_len = palindromic_length(i, palindromic_lengths[i] + 1, processed_string)
            palindromic_lengths[i] += expanded_len

            if (i + palindromic_lengths[i] > right) {
                center = i
                right = i + palindromic_lengths[i]
            }

            if (palindromic_lengths[i] > max_len) {
                max_len = palindromic_lengths[i]
                max_center = i
            }
        }

        let start = (max_center - max_len) / 2
        let end = start + max_len
        return this.input_string.runes().slice(start, end).map({r: Rune => r.toString()}).join("")
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {
    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        for (i in 0..predicted_labels.size) {
            let predicted = predicted_labels[i]
            let true_val = true_labels[i]
            if (predicted == 1 && true_val == 1) {
                this.true_positives += 1
            } else if (predicted == 1 && true_val == 0) {
                this.false_positives += 1
            } else if (predicted == 0 && true_val == 1) {
                this.false_negatives += 1
            } else {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let numerator: Float64 = this.true_positives.toFloat64()
        let denominator: Float64 = numerator + this.false_positives.toFloat64()
        if (denominator == 0.0) { return 0.0 }
        return numerator / denominator
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let numerator: Float64 = this.true_positives.toFloat64()
        let denominator: Float64 = numerator + this.false_negatives.toFloat64()
        if (denominator == 0.0) { return 0.0 }
        return numerator / denominator
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        let p = this.precision(predicted_labels, true_labels)
        let r = this.recall(predicted_labels, true_labels)
        if (p + r == 0.0) { return 0.0 }
        return 2.0 * p * r / (p + r)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        let numerator: Float64 = this.true_positives.toFloat64() + this.true_negatives.toFloat64()
        let denominator: Float64 = numerator + this.false_positives.toFloat64() + this.false_negatives.toFloat64()
        if (denominator == 0.0) { return 0.0 }
        return numerator / denominator
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let single_mrr = {d: (ArrayList<Int64>, Int64) => {
            let (results, _) = d
            for (i, v) in results.enumerate() {
                if (v == 1) {
                    return 1.0 / (i + 1)
                }
            }
            return 0.0
        }}

        if (data is (ArrayList<Int64>, Int64)) {
            let mrr_val = single_mrr(data as (ArrayList<Int64>, Int64))
            return (mrr_val, ArrayList<Float64>([mrr_val]))
        } else {
            let data_list = data as ArrayList<(ArrayList<Int64>, Int64)>
            let mrrs = ArrayList<Float64>()
            var total = 0.0
            for d in data_list {
                let mrr_val = single_mrr(d)
                mrrs.add(mrr_val)
                total += mrr_val
            }
            return (total / data_list.size, mrrs)
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let single_map = {d: (ArrayList<Int64>, Int64) => {
            let (results, gt_num) = d
            var sum_precision = 0.0
            var correct = 0
            for (i, v) in results.enumerate() {
                if (v == 1) {
                    correct += 1
                    sum_precision += correct.toFloat64() / (i + 1).toFloat64()
                }
            }
            return sum_precision / gt_num.toFloat64()
        }}

        if (data is (ArrayList<Int64>, Int64)) {
            let map_val = single_map(data as (ArrayList<Int64>, Int64))
            return (map_val, ArrayList<Float64>([map_val]))
        } else {
            let data_list = data as ArrayList<(ArrayList<Int64>, Int64)>
            let maps = ArrayList<Float64>()
            var total = 0.0
            for d in data_list {
                let map_val = single_map(d)
                maps.add(map_val)
                total += map_val
            }
            return (total / data_list.size, maps)
        }
    }
}

import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        var mines_placed = 0
        while (mines_placed < k) {
            let x = Random.next(n)
            let y = Random.next(n)
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed += 1

                for (i in (x-1)..(x+2)) {
                    for (j in (y-1)..(y+2)) {
                        if (i >= 0 && i < n && j >= 0 && j < n && map[i][j] != "X") {
                            let current = Parsable.parseInt64(map[i][j])
                            map[i][j] = Parsable.toString(current + 1)
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (_ in 0..n) {
            var row = ArrayList<String>()
            for (_ in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (minesweeper_map[i][j] != "X" && map[i][j] == "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            return false
        }

        if (player_map[x][y] != "-") {
            return player_map
        }

        player_map[x][y] = minesweeper_map[x][y]
        if (check_won(player_map)) {
            return true
        }

        if (minesweeper_map[x][y] == "0") {
            for (i in (x-1)..(x+2)) {
                for (j in (y-1)..(y+2)) {
                    if (i >= 0 && i < n && j >= 0 && j < n && !(i == x && j == y)) {
                        sweep(i, j)
                    }
                }
            }
        }
        return player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let seats = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.add(0)
            }
            seats.add(row)
        }
        let movie = HashMap<String, Any>([
            ("name", name),
            ("price", price),
            ("start_time", DateTime.parse(start_time, "yyyy/MM/dd HH:mm")),
            ("end_time", DateTime.parse(end_time, "yyyy/MM/dd HH:mm")),
            ("seats", seats)
        ])
        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        let mut movie_found = false
        let mut booking_success = true

        for movie in movies {
            if movie["name"] == name {
                movie_found = true
                let seats = movie["seats"] as ArrayList<ArrayList<Int64>>

                // First check all seats are available
                for seat_pair in seats_to_book {
                    let row = seat_pair[0]
                    let col = seat_pair[1]
                    if row >= seats.size || col >= seats[0].size || seats[row][col] != 0 {
                        booking_success = false
                        break
                    }
                }

                // Then mark seats as booked
                if booking_success {
                    for seat_pair in seats_to_book {
                        let row = seat_pair[0]
                        let col = seat_pair[1]
                        seats[row][col] = 1
                    }
                }
                break
            }
        }

        if !movie_found {
            return "Movie not found."
        } else if booking_success {
            return "Booking success."
        } else {
            return "Booking failed."
        }
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let result = ArrayList<String>()
        let start_dt = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end_dt = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        for movie in movies {
            let movie_start = movie["start_time"] as DateTime
            let movie_end = movie["end_time"] as DateTime

            if (movie_start <= end_dt) && (movie_end >= start_dt) {
                result.add(movie["name"] as String)
            }
        }

        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {
    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        let index = this.playlist.indexOf(song)
        if (index != -1) {
            this.playlist.remove(at: index)
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }
        if (this.current_song.isNone()) {
            this.current_song = Some(this.playlist[0])
        }
        return this.current_song
    }

    public func stop(): Bool {
        if (this.current_song.isNone()) {
            return false
        }
        this.current_song = None
        return true
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song.isNone()) {
            return false
        }
        let current = this.current_song.getOrThrow()
        let index = this.playlist.indexOf(current)
        if (index == -1 || index == this.playlist.size - 1) {
            return false
        }
        this.current_song = Some(this.playlist[index + 1])
        return true
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song.isNone()) {
            return false
        }
        let current = this.current_song.getOrThrow()
        let index = this.playlist.indexOf(current)
        if (index == -1 || index == 0) {
            return false
        }
        this.current_song = Some(this.playlist[index - 1])
        return true
    }

    public func set_volume(volume: Int64): Bool {
        if (volume < 0 || volume > 100) {
            return false
        }
        this.volume = volume
        return true
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let rand = Random()
        for (i in 0..this.playlist.size) {
            let j = rand.next(this.playlist.size)
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        return true
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    /*
    The class processes NLP data by removing stop words from a list of strings using a pre-defined stop word list.
    */

    public func construct_stop_word_list(): ArrayList<String> {
        /*
        Construct a stop word list including 'a', 'an', 'the'.
        :return: a list of stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.construct_stop_word_list()
        ['a', 'an', 'the']
        */
        return ArrayList<String>(["a", "an", "the"])
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :param stop_word_list: a list of stop words
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.process(ArrayList<String>(['This is a test.']), ArrayList<String>(['a', 'an', 'the']))
        [['This', 'is', 'test.']]
        */
        let result = ArrayList<ArrayList<String>>([])
        for (s in string_list) {
            let words = ArrayList<String>(s.split(" "))
            let filtered = ArrayList<String>([])
            for (word in words) {
                if (!stop_word_list.contains(word)) {
                    filtered.add(word)
                }
            }
            result.add(filtered)
        }
        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Construct a stop word list including 'a', 'an', 'the', and remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.']))
        [['This', 'is', 'test.']]
        */
        let stop_word_list = construct_stop_word_list()
        return remove_stop_words(string_list, stop_word_list)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let regex = Regex("[^a-zA-Z ]")
        let words_list = ArrayList<ArrayList<String>>([])

        for (s in string_list) {
            let cleaned = regex.replace_all(s, "")
            let lower = cleaned.toLowerCase()
            let words = lower.split(" ").filter({w: String => w.size > 0})
            words_list.add(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq_map = HashMap<String, Int64>([])

        for (words in words_list) {
            for (word in words) {
                let count = freq_map.get(word) ?? 0
                freq_map.add(word, count + 1)
            }
        }

        let entries = freq_map.entries().toArray()
        sort(entries, lessThan: {l: (String, Int64), r: (String, Int64) => l[1] < r[1]}, descending: true)

        let top5 = HashMap<String, Int64>([])
        for (i in 0..min(5, entries.size)) {
            top5.add(entries[i][0], entries[i][1])
        }

        return top5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {
    public static func decimal_to_binary(decimal_num: Int64): String {
        return decimal_num.format(radix: 2)
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        return binary_num.parse(radix: 2).getOrThrow()
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        return decimal_num.format(radix: 8)
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        return octal_num.parse(radix: 8).getOrThrow()
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        return decimal_num.format(radix: 16)
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        return hex_num.parse(radix: 16).getOrThrow()
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None<String> => ""
            case Some<String>(s) => this.format_string(s)
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let int_part = parts[0]
        let dec_part = if (parts.size > 1) { parts[1] } else { "0" }

        let int_words = this.format_integer(int_part)
        let dec_words = this.format_decimal(dec_part)

        let result = if (dec_words != "") {
            "${int_words} AND ${dec_words}"
        } else {
            int_words
        }
        "${result} ONLY"
    }

    private func format_integer(s: String): String {
        let len = s.size
        if (len <= 3) {
            this.trans_three(s.fillStart('0', 3 - len))
        } else {
            let chunks = ArrayList<String>()
            var i = len
            while (i > 0) {
                let start = if (i - 3 >= 0) { i - 3 } else { 0 }
                chunks.add(s.substring(start, i), at: 0)
                i = start
            }

            let words = ArrayList<String>()
            for (i in 0..chunks.size) {
                let chunk_words = this.trans_three(chunks[i].fillStart('0', 3 - chunks[i].size))
                if (chunk_words != "") {
                    words.add(chunk_words)
                    words.add(this.parse_more(chunks.size - i - 1))
                }
            }
            words.join(" ")
        }
    }

    private func format_decimal(s: String): String {
        if (s == "0" || s == "00") {
            ""
        } else if (s.size == 1) {
            this.trans_two("${s}0")
        } else {
            this.trans_two(s.substring(0, 2))
        }
    }

    public func trans_two(s: String): String {
        let num = s.toInt64()
        if (num < 10) {
            this.NUMBER[num]
        } else if (num < 20) {
            this.NUMBER_TEEN[num - 10]
        } else {
            let tens = num / 10
            let units = num % 10
            if (units == 0) {
                this.NUMBER_TEN[tens - 1]
            } else {
                "${this.NUMBER_TEN[tens - 1]} ${this.NUMBER[units]}"
            }
        }
    }

    public func trans_three(s: String): String {
        let num = s.toInt64()
        if (num == 0) {
            ""
        } else if (num < 100) {
            this.trans_two(s.substring(1))
        } else {
            let hundreds = num / 100
            let remainder = num % 100
            if (remainder == 0) {
                "${this.NUMBER[hundreds]} HUNDRED"
            } else {
                "${this.NUMBER[hundreds]} HUNDRED AND ${this.trans_two(remainder.toString())}"
            }
        }
    }

    public func parse_more(i: Int64): String {
        if (i < 0 || i >= this.NUMBER_MORE.size) {
            ""
        } else {
            this.NUMBER_MORE[i]
        }
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let result = ArrayList<Rune>()
        let chars = string.toRuneArray()
        var i = 0

        while (i < chars.size) {
            if (chars[i] == r'&' && i + 3 < chars.size && chars[i + 1] == r'#') {
                let start = i + 2
                var isHex = false
                var radix = 10

                if (chars[start] == r'x' || chars[start] == r'X') {
                    isHex = true
                    radix = 16
                    i += 1
                }

                var j = start + (if (isHex) {1} else {0})
                let codeStart = j
                while (j < chars.size && chars[j].isDigit(radix: radix)) {
                    j += 1
                }

                if (j < chars.size && chars[j] == r';') {
                    let numStr = String.fromRuneArray(chars.slice(from: codeStart, to: j))
                    if let num = numStr.toInt(radix: radix) {
                        result.add(Rune(num))
                        i = j + 1
                        continue
                    }
                }
            }
            result.add(chars[i])
            i += 1
        }

        return String.fromRuneArray(result.toArray())
    }

    public static func is_hex_char(char: Rune): Bool {
        (char >= r'0' && char <= r'9') || 
        (char >= r'a' && char <= r'f') || 
        (char >= r'A' && char <= r'F')
    }
}

