import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = ArrayList<Int64>([this.positions[0][0] + direction[0] * this.BLOCK_SIZE, this.positions[0][1] + direction[1] * this.BLOCK_SIZE])

        // Check if snake hit itself
        for i in 0..this.positions.size {
            if (head[0] == this.positions[i][0] && head[1] == this.positions[i][1]) {
                this.reset()
                return
            }
        }

        // Add new head position
        this.positions.add(head, at: 0)

        // Check if snake ate food
        if (head[0] == this.food_position[0] && head[1] == this.food_position[1]) {
            this.eat_food()
        } else {
            // Remove tail if no food eaten
            this.positions.remove(at: this.positions.size - 1)
        }
    }

    public func random_food_position(): Unit {
        let random = Random()
        while (true) {
            let x = random.nextInt64(0..(this.SCREEN_WIDTH / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            let y = random.nextInt64(0..(this.SCREEN_HEIGHT / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            let new_position = ArrayList<Int64>([x, y])

            var collision = false
            for i in 0..this.positions.size {
                if (new_position[0] == this.positions[i][0] && new_position[1] == this.positions[i][1]) {
                    collision = true
                    break
                }
            }

            if (!collision) {
                this.food_position = new_position
                return
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length = this.length + 1
        this.score = this.score + 100
        this.random_food_position()
    }
}

