class SQLQueryBuilder {
    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        let cols = columns.join(",")
        var query = "SELECT ${cols} FROM ${table}"

        match (where_condition) {
            case Some(cond) => {
                let conditions = cond.map({k, v => "${k}='${v}'"}).join(" AND ")
                query = query + " WHERE ${conditions}"
            }
            case None => {}
        }

        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        let columns = data.keys().join(",")
        let values = data.values().map({v => "'${v}'"}).join(",")
        return "INSERT INTO ${table} (${columns}) VALUES (${values})"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM ${table}"

        match (where_condition) {
            case Some(cond) => {
                let conditions = cond.map({k, v => "${k}='${v}'"}).join(" AND ")
                query = query + " WHERE ${conditions}"
            }
            case None => {}
        }

        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        let set_clause = data.map({k, v => "${k}='${v}'"}).join(",")
        var query = "UPDATE ${table} SET ${set_clause}"

        match (where_condition) {
            case Some(cond) => {
                let conditions = cond.map({k,assembly v => "${k}='${v}'"}).join(" AND ")
                query = query + " WHERE ${conditions}"
            }
            case None => {}
        }

        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            throw "Empty data"
        }
        var sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        var maxCount = 0

        for (item in data) {
            let count = freq.get(item) ?? 0 + 1
            freq.add(item, count)
            if (count > maxCount) {
                maxCount = count
            }
        }

        let result = ArrayList<Int64>()
        for (entry in freq) {
            if (entry.value == maxCount) {
                result.add(entry.key)
            }
        }
        sort(result)
        return result
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let xMeanOption = mean(x)
        let yMeanOption = mean(y)
        if (xMeanOption is None<Float64> || yMeanOption is None<Float64>) {
            return None<Float64>()
        }
        let xMean = xMeanOption.getOrThrow()
        let yMean = yMeanOption.getOrThrow()

        var sumXY = 0.0
        var sumX2 = 0.0
        var sumY2 = 0.0

        for (i in 0..x.size) {
            let xDiff = Float64(x[i]) - xMean
            let yDiff = Float64(y[i]) - yMean
            sumXY += xDiff * yDiff
            sumX2 += xDiff * xDiff
            sumY2 += yDiff * yDiff
        }

        let denominator = sqrt(sumX2 * sumY2)
        if (denominator == 0.0) {
            return None<Float64>()
        }
        return Some<Float64>(sumXY / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        var sum = 0.0
        for (item in data) {
            sum += Float64(item)
        }
        return Some<Float64>(sum / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()

        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let corr = correlation(data[i], data[j])
                row.add(corr.getOrElse(0.0))
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanOption = mean(data)
        if (meanOption is None<Float64>) {
            return None<Float64>()
        }
        let meanValue = meanOption.getOrThrow()

        var sum = 0.0
        for (item in data) {
            let diff = Float64(item) - meanValue
            sum += diff * diff
        }

        return Some<Float64>(sqrt(sum / Float64(data.size)))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanOption = mean(data)
        let stdOption = standard_deviation(data)
        if (meanOption is None<Float64> || stdOption is None<Float64> || stdOption.getOrThrow() == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let meanValue = meanOption.getOrThrow()
        let std = stdOption.getOrThrow()

        let result = ArrayList<Float64>()
        for (item in data) {
            result.add((Float64(item) - meanValue) / std)
        }
        return Some<ArrayList<Float64>>(result)
    }
}

