class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        for (i in 0..this.portfolio.size) {
            if (this.portfolio[i] == stock) {
                this.portfolio.remove(at: i)
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let total_cost = stock.price * Float64(stock.quantity)
        if (this.cash_balance >= total_cost) {
            this.cash_balance -= total_cost
            this.portfolio.add(stock)
            return true
        }
        return false
    }

    public func sell_stock(stock: Stock): Bool {
        for (i in 0..this.portfolio.size) {
            let port_stock = this.portfolio[i]
            if (port_stock.name == stock.name) {
                if (port_stock.quantity >= stock.quantity) {
                    this.cash_balance += stock.price * Float64(stock.quantity)
                    port_stock.quantity -= stock.quantity
                    if (port_stock.quantity == 0) {
                        this.portfolio.remove(at: i)
                    }
                    return true
                }
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var total: Float64 = this.cash_balance
        for (stock in this.portfolio) {
            total += stock.price * Float64(stock.quantity)
        }
        return total
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        var summary = ArrayList<HashMap<String, Any>>()
        var total: Float64 = this.cash_balance

        for (stock in this.portfolio) {
            let value = stock.price * Float64(stock.quantity)
            total += value
            let entry = HashMap<String, Any>([("name", stock.name), ("value", value)])
            summary.add(entry)
        }

        return (total, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }
}

import std.math.abs

class Thermostat {
    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        if (mode == "heat" || mode == "cool") {
            this.mode = mode
            return true
        }
        return false
    }

    public func auto_set_mode(): Unit {
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        let should_be_heat = this.current_temperature < this.target_temperature
        let current_is_heat = this.mode == "heat"
        if (should_be_heat != current_is_heat) {
            this.auto_set_mode()
            return false
        }
        return true
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var time: Int64 = 0
        while (true) {
            if (abs(this.current_temperature - this.target_temperature) < 0.1) {
                break
            }
            if (this.mode == "heat") {
                this.current_temperature += 1.0
            } else {
                this.current_temperature -= 1.0
            }
            time += 1
        }
        return time
    }
}

import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= this.board.size || col < 0 || col >= this.board[0].size || this.board[row][col] != " ") {
            return false
        }
        this.board[row][col] = this.current_player
        this.current_player = if (this.current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        // Check rows
        for (row in 0..this.board.size) {
            let first = this.board[row][0]
            if (first != " ") {
                var all_same = true
                for (col in 1..this.board[row].size) {
                    if (this.board[row][col] != first) {
                        all_same = false
                        break
                    }
                }
                if (all_same) {
                    return Some<String>(first)
                }
            }
        }

        // Check columns
        for (col in 0..this.board[0].size) {
            let first = this.board[0][col]
            if (first != " ") {
                var all_same = true
                for (row in 1..this.board.size) {
                    if (this.board[row][col] != first) {
                        all_same = false
                        break
                    }
                }
                if (all_same) {
                    return Some<String>(first)
                }
            }
        }

        // Check diagonal 1
        let first_diag1 = this.board[0][0]
        if (first_diag1 != " ") {
            var all_same = true
            for (i in 1..this.board.size) {
                if (this.board[i][i] != first_diag1) {
                    all_same = false
                    break
                }
            }
            if (all_same) {
                return Some<String>(first_diag1)
            }
        }

        // Check diagonal 2
        let n = this.board.size - 1
        let first_diag2 = this.board[0][n]
        if (first_diag2 != " ") {
            var all_same = true
            for (i in 1..this.board.size) {
                if (this.board[i][n - i] != first_diag2) {
                    all_same = false
                    break
                }
            }
            if (all_same) {
                return Some<String>(first_diag2)
            }
        }

        return None<String>()
    }

    public func is_board_full(): Bool {
        for (row in 0..this.board.size) {
            for (col in 0..this.board[row].size) {
                if (this.board[row][col] == " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.time.DateTime
import std.math.round

class TimeUtils {

    /*
    This is a time util class, including getting the current time and date, adding seconds to a datetime, converting between strings and datetime objects, calculating the time difference in minutes, and formatting a datetime object.
    */

    let datetime: DateTime

    public init() {
        /*
        Get the current datetime
        */
        this.datetime = DateTime.now()
    }

    public func get_current_time(): String {
        /*
        Return the current time in the format of 'HH:mm:ss'
        :return: String
        >>> timeutils = TimeUtils()
        >>> timeutils.get_current_time()
        "19:19:22"
        */
        return "${this.datetime.hour}:${this.datetime.minute}:${this.datetime.second}"
    }

    public func get_current_date(): String {
        /*
        Return the current date in the format of "yyyy-MM-dd"
        :return: String
        >>> timeutils.get_current_date()
        "2023-06-14"
        */
        return "${this.datetime.year}-${this.datetime.month}-${this.datetime.day}"
    }

    public func add_seconds(seconds: Int64): String {
        /*
        Add the specified number of seconds to the current time
        :param seconds: Int64, number of seconds to add
        :return: String, time after adding the specified number of seconds in the format 'HH:mm:ss'
        >>> timeutils.add_seconds(600)
        "19:29:22"
        */
        let new_time = this.datetime.addSeconds(seconds)
        return "${new_time.hour}:${new_time.minute}:${new_time.second}"
    }

    public func string_to_datetime(string: String): DateTime {
        /*
        Convert the time string to a datetime instance
        :param string: String, string before converting format
        :return: DateTime
        >>> timeutils.string_to_datetime("2001-07-18 01:01:01")
        2001-07-18 01:01:01
        */
        return DateTime.parse(string, format: "yyyy-MM-dd HH:mm:ss")
    }

    public func datetime_to_string(datetime: DateTime): String {
        /*
        Convert a datetime instance to a string
        :param datetime: the DatetTime instance to convert
        :return: String, converted time string
        >>> timeutils.datetime_to_string(timeutils.datetime)
        "2023-06-14 19:30:03"
        */
        return "${datetime.year}-${datetime.month}-${datetime.day} ${datetime.hour}:${datetime.minute}:${datetime.second}"
    }

    public func get_minutes(string_time1: String, string_time2: String): Int64 {
        /*
        Calculate how many minutes have passed between two times, and round the results to the nearest
        :return: Int64, the number of minutes between two times, rounded off
        >>> timeutils.get_minutes("2001-07-18 01:01:01", "2001-07-18 02:01:01")
        60
        */
        let dt1 = this.string_to_datetime(string_time1)
        let dt2 = this.string_to_datetime(string_time2)
        let diff_seconds = (dt2.timestamp - dt1.timestamp)
        return round(diff_seconds / 60)
    }

    public func get_format_time(year: Int64, month: Int64, day: Int64, hour: Int64, minute: Int64, second: Int64): String {
        /*
        get format time
        :param year: Int64
        :param month: Int64
        :param day: Int64
        :param hour: Int64
        :param minute: Int64
        :param second: Int64
        :return: formatted time string
        >>> timeutils.get_format_time(2001, 7, 18, 1, 1, 1)
        "2001-07-18 01:01:01"
        */
        return "${year}-${month}-${day} ${hour}:${minute}:${second}"
    }
}

import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {
    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        let epsilon = 1e-15
        var result = 0.0
        var term = 1.0
        var sign = 1.0
        var i = 0

        while (abs(term) > epsilon) {
            result += term
            i += 2
            sign *= -1
            term = sign * pow(rad, i.toFloat64()) / factorial(i.toInt64()).toFloat64()
        }
        return result
    }

    public func factorial(a: Int64): Decimal {
        if (a <= 1) {
            return Decimal(1)
        }
        var result = Decimal(1)
        for (i in 2..a+1) {
            result *= Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let rad = x * PI / 180.0
        var result = 0.0
        var sign = 1.0

        for (i in 0..n) {
            let term = sign * pow(rad, (2*i).toFloat64()) / factorial((2*i).toInt64()).toFloat64()
            result += term
            sign *= -1
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let rad = x * PI / 180.0
        let epsilon = 1e-15
        var result = 0.0
        var term = rad
        var sign = 1.0
        var i = 1

        while (abs(term) > epsilon) {
            result += term
            i += 2
            sign *= -1
            term = sign * pow(rad, i.toFloat64()) / factorial(i.toInt64()).toFloat64()
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cosVal = this.cos(x)
        if (abs(cosVal) < 0.000001) {
            return None<Float64>()
        }
        return Some<Float64>(this.sin(x) / cosVal)
    }
}

