    }

    public func _generate_cards(): Unit {
        let random = Random()
        this.nums.clear()
        for _ in 0..4 {
            this.nums.add(random.nextInt64(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        let parser = Parser(expression)
        let result = parser.parse()

        var expr_nums = HashSet<Int64>()
        let expr_str = expression.replaceAll(" ", "")
        var temp_num_str = ""

        for ch in expr_str.runes() {
            if (ch.isAsciiNumber()) {
                temp_num_str += ch.toChar()
            } else {
                if (temp_num_str != "") {
                    expr_nums.add(Int64.parse(temp_num_str))
                    temp_num_str = ""
                }
            }
        }

        if (temp_num_str != "") {
            expr_nums.add(Int64.parse(temp_num_str))
        }

        var game_nums = HashSet<Int64>(this.nums.toArray())
        return result == 24 && expr_nums == game_nums
    }

    public func evaluate_expression(expression: String): Bool {
        let parser = Parser(expression)
        return parser.parse() == 24
    }
}

import std.collection.HashMap

class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let parts = url.split(separator: "://", max: 2)
        if (parts.size > 1) {
            return Some<String>(parts[0])
        }
        return None<String>()
    }

    public func get_host(): Option<String> {
        let scheme_parts = url.split(separator: "://", max: 2)
        if (scheme_parts.size <= 1) {
            return None<String>()
        }
        let slash_pos = scheme_parts[1].find("/")
        if (slash_pos == -1) {
            return Some<String>(scheme_parts[1])
        }
        return Some<String>(scheme_parts[1].substring(0, slash_pos))
    }

    public func get_path(): Option<String> {
        let scheme_parts = url.split(separator: "://", max: 2)
        if (scheme_parts.size <= 1) {
            return Some<String>(url)
        }
        let slash_pos = scheme_parts[1].find("/")
        if (slash_pos == -1) {
            return Some<String>("/")
        }
        return Some<String>(scheme_parts[1].substring(slash_pos))
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let path_result = get_path()
        if (path_result is None<String>) {
            return None<HashMap<String, String>>()
        }
        let path = path_result.getOrThrow()
        let query_start = path.find("?")
        if (query_start == -1) {
            return None<HashMap<String, String>>()
        }
        let query_str = path.substring(query_start + 1)
        let frag_pos = query_str.find("#")
        let final_query_str = if (frag_pos == -1) { query_str } else { query_str.substring(0, frag_pos) }

        let params_map = HashMap<String, String>()
        for (pair in final_query_str.split("&")) {
            let kv = pair.split("=", max: 2)
            if (kv.size == 2) {
                params_map.add(kv[0], kv[1])
            }
        }
        return Some<HashMap<String, String>>(params_map)
    }

    public func get_fragment(): Option<String> {
        let hash_pos = url.find("#")
        if (hash_pos == -1) {
            return None<String>()
        }
        return Some<String>(url.substring(hash_pos + 1))
    }
}

import std.collection.ArrayList

class UrlPath {
    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixed = UrlPath.fix_path(path)
        if (fixed.size == 0) {
            return
        }
        for seg in fixed.split("/") {
            this.segments.add(seg)
        }
    }

    public static func fix_path(path: String): String {
        let mut p = path
        while (p.size > 0 && p[0] == '/') {
            p = p.substring(1)
        }
        while (p.size > 0 && p[p.size - 1] == '/') {
            p = p.substring(0, p.size - 1)
        }
        return p
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let mut dot_product = 0.0
        let mut norm_1 = 0.0
        let mut norm_2 = 0.0

        for (i in 0..vector_1.size) {
            dot_product += vector_1[i] * vector_2[i]
            norm_1 += pow(vector_1[i], 2)
            norm_2 += pow(vector_2[i], 2)
        }

        norm_1 = sqrt(norm_1)
        norm_2 = sqrt(norm_2)

        if (norm_1 == 0.0 || norm_2 == 0.0) {
            return 0.0
        }

        return dot_product / (norm_1 * norm_2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let mut similarities = ArrayList<Float64>([])

        for (v in vectors_all) {
            similarities.add(similarity(vector_1, v))
        }

        return similarities
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let mut avg_vec_1 = ArrayList<Float64>([])
        let mut avg_vec_2 = ArrayList<Float64>([])

        // Initialize average vectors with zeros
        if (vector_list_1.size > 0) {
            for (_ in 0..vector_list_1[0].size) {
                avg_vec_1.add(0.0)
                avg_vec_2.add(0.0)
            }
        }

        // Compute average of first list
        for (vec in vector_list_1) {
            for (i in 0..vec.size) {
                avg_vec_1[i] += vec[i]
            }
        }

        // Compute average of second list
        for (vec in vector_list_2) {
            for (i in 0..vec.size) {
                avg_vec_2[i] += vec[i]
            }
        }

        // Divide by count to get average
        for (i in 0..avg_vec_1.size) {
            avg_vec_1[i] /= vector_list_1.size.toFloat64()
            avg_vec_2[i] /= vector_list_2.size.toFloat64()
        }

        return similarity(avg_vec_1, avg_vec_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let mut result = HashMap<String, Float64>([])

        for (entry in number_dict) {
            let (key, count) = entry
            let weight = log((total_num.toFloat64() + 1.0) / (count + 1.0))
            result.add(key, weight)
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Product <: Equatable<Product> {

    let price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price =price
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class VendingMachine {

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        this.inventory.add(item_name, Product(price, quantity))
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        let product_option = this.inventory.get(item_name)
        match (product_option) {
            case Some(product) {
                if (product.quantity > 0 && this.balance >= product.price) {
                    product.quantity -= 1
                    this.balance -= product.price
                    return Some(this.balance)
                }
                return None
            }
            case None => return None
        }
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        let product_option = this.inventory.get(item_name)
        match (product_option) {
            case Some(product) {
                product.quantity += quantity
                return true
            }
            case None => return false
        }
    }

    public func display_items(): Option<String> {
        if (this.inventory.size == 0) {
            return None
        }

        let result = ArrayList<String>()
        for (entry in this.inventory) {
            let item_name = entry[0]
            let product = entry[1]
            result.add("${item_name} - $${product.price} [${product.quantity}]")
        }
        return Some(result.join(", "))
    }
}

import std.collection.HashMap

class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        match (this.inventory.get(product_id)) {
            case Some(p: Product) => p.quantity += quantity
            case None => this.inventory.add(product_id, Product(name, quantity))
        }
    }

    public func update_product_quantity(product_id: Int64,quantity: Int64): Unit {
        match (this.inventory.get(product_id)) {
            case Some(p: Product) => p.quantity += quantity
            case None => ()
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        match (this.inventory.get(product_id)) {
            case Some(p: Product) => Some(p.quantity)
            case None => None
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        match (this.inventory.get(product_id)) {
            case Some(p: Product) => {
                if (p.quantity >= quantity) {
                    p.quantity -= quantity
                    this.orders.add(order_id, Order(product_id, quantity, "Shipped"))
                    true
                } else {
                    false
                }
            }
            case None => false
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        match (this.orders.get(order_id)) {
            case Some(o: Order) => {
                o.status = status
                true
            }
            case None => false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        match (this.orders.get(order_id)) {
            case Some(o: Order) => Some(o.status)
            case None => None
        }
    }
}

